#!/usr/bin/env python3
"""VELMARA - travel poster for a place that isn't there.

Entry for the make.fun bounty "The Poster for a Place That Isn't There".
The poster is a 1024x1024 PNG of Velmara, an island in the fictional
Meridia archipelago where the waterfalls fall UPWARD from the sea to
floating islands. Deep teal and gold at dusk; the name VELMARA is set in
large serif type at the top, with the tagline "WHERE THE WATER CLIMBS
THE SKY" beneath it and "MERIDIA ARCHIPELAGO" at the bottom.

Stdlib only: the PNG is embedded below as a single base64 string and is
decoded and written to /output/entry.png at runtime.
"""

import base64
import os
import struct
import sys

# The poster image (1024x1024 PNG), one single-line base64 string.
_B64 = ""

OUTPUT_PATH = "/output/entry.png"
_PNG_SIGNATURE = b"\x89PNG\r\n\x1a\n"


def _check_png(data: bytes) -> tuple[int, int]:
    """Validate the PNG signature and read the IHDR dimensions (stdlib)."""
    if data[:8] != _PNG_SIGNATURE:
        raise ValueError("embedded data is not a PNG")
    width, height = struct.unpack(">II", data[16:24])
    return width, height


def main(argv: list[str] | None = None) -> int:
    # Optional first argument overrides the output path (for local checks);
    # the grader runs with no arguments and gets /output/entry.png.
    out_path = argv[1] if argv and len(argv) > 1 else OUTPUT_PATH
    data = base64.b64decode(_B64)
    width, height = _check_png(data)
    if (width, height) != (1024, 1024):
        raise ValueError(f"poster is {width}x{height}, expected 1024x1024")
    if len(data) > 1_048_576:
        raise ValueError(f"poster is {len(data)} bytes, over the 1 MiB limit")
    os.makedirs(os.path.dirname(out_path) or ".", exist_ok=True)
    # Write atomically so a failed run can never leave a partial PNG behind.
    tmp_path = out_path + ".tmp"
    with open(tmp_path, "wb") as fh:
        fh.write(data)
    os.replace(tmp_path, out_path)
    print(f"wrote {out_path} ({len(data)} bytes, {width}x{height})")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))


if __name__ == "__main__":
    sys.exit(main())
